-- LootJinx – Lokalisierung (10 Sprachen)
local ADDON, ns = ...
local LJ = ns or _G.LootJinx or {}
_G.LootJinx = LJ

local LOCALE_LANG = {
    deDE = "de",
    enUS = "en", enGB = "en", enTW = "en", enCN = "en",
    esES = "es", esMX = "es",
    frFR = "fr",
    itIT = "it",
    ptBR = "pt", ptPT = "pt",
    ruRU = "ru",
    koKR = "ko",
    zhCN = "zhCN",
    zhTW = "zhTW",
}

local locale = (GetLocale and GetLocale()) or "enUS"
LJ.locale = locale
LJ.lang = LOCALE_LANG[locale] or "en"

-- Auswählbare Sprachen. Namen in lateinischer Schrift, damit sie auf jedem
-- Client (auch ohne CJK-/kyrillische Fonts) korrekt dargestellt werden.
LJ.LOCALES = {
    { code = "auto", name = "Auto" },
    { code = "en", name = "English" },
    { code = "de", name = "Deutsch" },
    { code = "es", name = "Español" },
    { code = "fr", name = "Français" },
    { code = "it", name = "Italiano" },
    { code = "pt", name = "Português" },
    { code = "ru", name = "Russian" },
    { code = "ko", name = "Korean" },
    { code = "zhCN", name = "Chinese (Simplified)" },
    { code = "zhTW", name = "Chinese (Traditional)" },
}

-- Löst eine gespeicherte Sprachauswahl auf die tatsächlich angewendete
-- Sprache auf. "auto" hängt vom Client ab; so lässt sich vor einem
-- Sprachwechsel erkennen, ob sich überhaupt etwas ändert.
function LJ:LanguageFor(lang)
    if lang == "auto" or lang == nil or lang == "" then
        return LOCALE_LANG[self.locale] or "en"
    end
    return lang
end

function LJ:SetLanguage(lang)
    self.lang = self:LanguageFor(lang)
end

