    YESTERDAY = { de = "Gestern", en = "Yesterday", es = "Ayer", fr = "Hier", it = "Ieri", pt = "Ontem", ru = "Вчера", ko = "어제", zhCN = "昨天", zhTW = "昨天" },


    TT_NEED_TITLE = { de = "Need-Rolls", en = "Need Rolls", es = "Tiradas de necesidad", fr = "Jets de besoin", it = "Tiri di bisogno", pt = "Rolagens de necessidade", ru = "Броски нужды", ko = "차비 주사위", zhCN = "需求掷骰", zhTW = "需求擲骰" },
    TT_NEED_1 = { de = "Zählt ausschließlich Need-Würfe. Gier-Würfe und per Gier gewonnene Items werden komplett ignoriert.", en = "Counts only need rolls. Greed rolls and items won with greed are ignored completely.", es = "Cuenta solo tiradas de necesidad. Las tiradas de codicia y los objetos ganados por codicia se ignoran por completo.", fr = "Compte uniquement les jets de besoin. Les jets de cupidité et les objets gagnés par cupidité sont totalement ignorés.", it = "Conta solo i tiri di bisogno. I tiri di avidità e gli oggetti vinti con avidità vengono ignorati del tutto.", pt = "Conta apenas rolagens de necessidade. Rolagens de ganância e itens vencidos por ganância são totalmente ignorados.", ru = "Считает только броски нужды. Броски алчности и предметы, выигранные алчностью, полностью игнорируются.", ko = "차비 주사위만 셉니다. 탐욕 주사위와 탐욕으로 얻은 아이템은 완전히 무시됩니다.", zhCN = "仅统计需求掷骰。贪婪掷骰和贪婪赢得的物品完全忽略。", zhTW = "僅統計需求擲骰。貪婪擲骰和貪婪贏得的物品完全忽略。" },
    TT_NEED_2 = { de = "Serie: verlorene Need-Rolls in Folge. Rekord: die längste solche Folge.", en = "Streak: lost need rolls in a row. Record: the longest such streak.", es = "Racha: tiradas de necesidad perdidas consecutivas. Récord: la racha más larga de ese tipo.", fr = "Série : jets de besoin perdus d'affilée. Record : la plus longue série de ce type.", it = "Serie: tiri di bisogno persi di fila. Record: la serie più lunga di questo tipo.", pt = "Sequência: rolagens de necessidade perdidas em sequência. Recorde: a maior sequência desse tipo.", ru = "Серия: проигранные броски нужды подряд. Рекорд: самая длинная такая серия.", ko = "연속: 연속으로 패배한 차비 주사위. 기록: 가장 긴 연속.", zhCN = "连续：连续失败的需求掷骰。纪录：最长的此类连续。", zhTW = "連續：連續失敗的需求擲骰。紀錄：最長的此類連續。" },
    TT_NEED_3 = { de = "Nur bestätigte Verluste erhöhen den Wert. Offene Ergebnisse bleiben offen und unterbrechen die Verlustserie nicht.", en = "Only confirmed losses increase the value. Pending outcomes stay pending and do not break the loss streak.", es = "Solo las derrotas confirmadas aumentan el valor. Los resultados pendientes siguen pendientes y no rompen la racha de derrotas.", fr = "Seules les défaites confirmées augmentent la valeur. Les résultats en attente restent en attente et ne brisent pas la série de défaites.", it = "Solo le sconfitte confermate aumentano il valore. Gli esiti in sospeso restano in sospeso e non interrompono la serie di sconfitte.", pt = "Apenas derrotas confirmadas aumentam o valor. Resultados pendentes permanecem pendentes e não quebram a sequência de derrotas.", ru = "Только подтверждённые поражения увеличивают значение. Ожидающие исходы остаются в ожидании и не прерывают серию поражений.", ko = "확인된 패배만 수치를 올립니다. 대기 중인 결과는 그대로 남아 패배 연속을 끊지 않습니다.", zhCN = "仅确认的失败会增加数值。待定结果保持待定，不会中断连败。", zhTW = "僅確認的失敗會增加數值。待定結果保持待定，不會中斷連敗。" },

    TT_NO_WIN_TITLE = { de = "Dungeons ohne Need-Win", en = "Dungeons without a Need win", es = "Mazmorras sin victoria de necesidad", fr = "Donjons sans victoire de besoin", it = "Sotterranei senza vittoria di bisogno", pt = "Masmorras sem vitória de necessidade", ru = "Подземелья без победы нужды", ko = "차비 승리 없는 던전", zhCN = "无需求获胜的地下城", zhTW = "無需求獲勝的地城" },
    TT_NO_WIN_1 = { de = "Dungeons mit mindestens einem Need-Wurf, in denen du keinen Need-Roll gewonnen hast.", en = "Dungeons with at least one need roll in which you won no need roll.", es = "Mazmorras con al menos una tirada de necesidad en las que no ganaste ninguna.", fr = "Donjons avec au moins un jet de besoin dans lesquels vous n'avez gagné aucun jet de besoin.", it = "Sotterranei con almeno un tiro di bisogno in cui non hai vinto alcun tiro di bisogno.", pt = "Masmorras com pelo menos uma rolagem de necessidade nas quais você não venceu nenhuma.", ru = "Подземелья хотя бы с одним броском нужды, в которых вы не выиграли ни одного броска.", ko = "차비 주사위가 최소 한 번 있었지만 단 한 번도 승리하지 못한 던전.", zhCN = "至少有一次需求掷骰但你未赢得任何一次的地下城。", zhTW = "至少有一次需求擲骰但你未贏得任何一次的地城。" },
    TT_NO_WIN_2 = { de = "Dungeons ganz ohne Need unterbrechen die Serie nicht.", en = "Dungeons without any need roll do not break the streak.", es = "Las mazmorras sin ninguna tirada de necesidad no rompen la racha.", fr = "Les donjons sans aucun jet de besoin ne brisent pas la série.", it = "I sotterranei senza alcun tiro di bisogno non interrompono la serie.", pt = "Masmorras sem nenhuma rolagem de necessidade não quebram a sequência.", ru = "Подземелья без бросков нужды не прерывают серию.", ko = "차비 주사위가 전혀 없는 던전은 연속을 끊지 않습니다.", zhCN = "完全没有需求掷骰的地下城不会中断连续。", zhTW = "完全沒有需求擲骰的地城不會中斷連續。" },
    TT_NO_WIN_3 = { de = "Ein Run mit offenem Need, aber ohne bestätigten Sieg zählt hier mit. Das gilt auch für unvollständige Runs.", en = "A run with a pending Need and no confirmed win counts here, including unfinished runs.", es = "Un run con necesidad pendiente y sin victoria confirmada cuenta aquí, incluidos los runs incompletos.", fr = "Un run avec un besoin en attente et sans victoire confirmée compte ici, y compris les runs incomplets.", it = "Un run con un bisogno in sospeso e senza vittoria confermata conta qui, inclusi i run incompleti.", pt = "Um run com necessidade pendente e sem vitória confirmada conta aqui, incluindo runs incompletos.", ru = "Забег с ожидающей нуждой и без подтверждённой победы засчитывается здесь, включая незавершённые.", ko = "대기 중인 차비가 있고 확인된 승리가 없는 런은 미완료 런을 포함해 여기에 집계됩니다.", zhCN = "有待定需求且无确认胜利的副本计入此处，包括未完成的副本。", zhTW = "有待定需求且無確認勝利的地城計入此處，包括未完成的地城。" },

    TT_NO_LOOT_TITLE = { de = "Dungeons ohne Loot", en = "Dungeons without loot", es = "Mazmorras sin botín", fr = "Donjons sans butin", it = "Sotterranei senza bottino", pt = "Masmorras sem saque", ru = "Подземелья без добычи", ko = "전리품 없는 던전", zhCN = "无掉落的地下城", zhTW = "無掉落的地城" },
    TT_NO_LOOT_1 = { de = "Dungeons, in denen überhaupt kein Item als Beute beobachtet wurde. Questitems zählen nicht.", en = "Dungeons where no item was observed as loot at all. Quest items are excluded.", es = "Mazmorras en las que no se observó ningún objeto como botín. Los objetos de misión quedan excluidos.", fr = "Donjons où aucun objet n'a été observé comme butin. Les objets de quête sont exclus.", it = "Sotterranei in cui non è stato osservato alcun oggetto come bottino. Gli oggetti delle missioni sono esclusi.", pt = "Masmorras onde nenhum item foi observado como saque. Itens de missão são excluídos.", ru = "Подземелья, в которых не наблюдалось ни одного предмета в качестве добычи. Предметы заданий исключаются.", ko = "전리품으로 관찰된 아이템이 전혀 없던 던전. 퀘스트 아이템은 제외됩니다.", zhCN = "未观察到任何掉落物品的地下城。任务物品不计入。", zhTW = "未觀察到任何掉落物品的地城。任務物品不計入。" },
    TT_NO_LOOT_2 = { de = "Auch unvollständige und manuell beendete Runs zählen. Fehlende Beobachtung ist kein Beweis für fehlende Beute.", en = "Unfinished and manually finished runs also count. Missing observation is not proof of missing loot.", es = "También cuentan los runs incompletos y terminados manualmente. La falta de observación no es prueba de falta de botín.", fr = "Les runs incomplets et terminés manuellement comptent aussi. L'absence d'observation n'est pas une preuve d'absence de butin.", it = "Contano anche i run incompleti e terminati manualmente. La mancata osservazione non è una prova di bottino mancante.", pt = "Runs incompletos e encerrados manualmente também contam. A falta de observação não é prova de saque ausente.", ru = "Незавершённые и завершённые вручную забеги тоже считаются. Отсутствие наблюдения не доказывает отсутствие добычи.", ko = "미완료 및 수동 종료된 런도 집계됩니다. 관찰이 없었다고 전리품이 없었다는 뜻은 아닙니다.", zhCN = "未完成和手动结束的副本也计入。未观察到并不能证明没有掉落。", zhTW = "未完成和手動結束的地城也計入。未觀察到並不能證明沒有掉落。" },

    TT_SINCE_TITLE = { de = "Seit letztem Need-Win", en = "Since the last Need win", es = "Desde la última victoria de necesidad", fr = "Depuis la dernière victoire de besoin", it = "Dall'ultima vittoria di bisogno", pt = "Desde a última vitória de necessidade", ru = "С последней победы нужды", ko = "마지막 차비 승리 이후", zhCN = "自上次需求获胜以来", zhTW = "自上次需求獲勝以來" },
    TT_SINCE_1 = { de = "Alle Dungeons seit deinem letzten gewonnenen Need-Roll – auch Dungeons ohne Need.", en = "Every dungeon since your last won need roll – including dungeons without a need roll.", es = "Cada mazmorra desde tu última tirada de necesidad ganada, incluidas las mazmorras sin tirada de necesidad.", fr = "Chaque donjon depuis votre dernier jet de besoin gagné – y compris les donjons sans jet de besoin.", it = "Ogni sotterraneo dall'ultimo tiro di bisogno vinto – inclusi i sotterranei senza tiri di bisogno.", pt = "Cada masmorra desde sua última rolagem de necessidade vencida – incluindo masmorras sem rolagem de necessidade.", ru = "Каждое подземелье с последнего выигранного броска нужды, включая подземелья без бросков нужды.", ko = "마지막으로 승리한 차비 주사위 이후의 모든 던전 – 차비 주사위가 없던 던전 포함.", zhCN = "自上次赢得需求掷骰以来的每个地下城，包括无需求掷骰的地下城。", zhTW = "自上次贏得需求擲骰以來的每個地城，包括無需求擲骰的地城。" },
    TT_SINCE_2 = { de = "Gier-Gewinne zählen nicht. Serie: aktueller Wert, Rekord: höchster Wert jemals.", en = "Greed wins do not count. Streak: current value, record: highest value ever.", es = "Las victorias por codicia no cuentan. Racha: valor actual, récord: valor más alto jamás.", fr = "Les victoires par cupidité ne comptent pas. Série : valeur actuelle, record : valeur la plus élevée jamais atteinte.", it = "Le vittorie per avidità non contano. Serie: valore attuale, record: valore più alto di sempre.", pt = "Vitórias por ganância não contam. Sequência: valor atual, recorde: maior valor já registrado.", ru = "Победы алчностью не считаются. Серия: текущее значение, рекорд: самое высокое значение.", ko = "탐욕 승리는 제외됩니다. 연속: 현재 수치, 기록: 역대 최고 수치.", zhCN = "贪婪获胜不计入。连续：当前值，纪录：历史最高值。", zhTW = "貪婪獲勝不計入。連續：當前值，紀錄：歷史最高值。" },
    TT_SINCE_3 = { de = "Die Zählung beginnt mit dem ersten Need-Wurf. Danach zählt jeder Run ohne bestätigten Need-Sieg, auch ein unvollständiger.", en = "Counting starts with the first Need roll. After that, every run without a confirmed Need win counts, including unfinished runs.", es = "El conteo comienza con la primera tirada de necesidad. Después, cuenta cada run sin victoria de necesidad confirmada, incluidos los incompletos.", fr = "Le décompte commence au premier jet de besoin. Ensuite, chaque run sans victoire de besoin confirmée compte, y compris les runs incomplets.", it = "Il conteggio inizia con il primo tiro di bisogno. Dopo, conta ogni run senza vittoria di bisogno confermata, inclusi i run incompleti.", pt = "A contagem começa com a primeira rolagem de necessidade. Depois, cada run sem vitória de necessidade confirmada conta, incluindo os incompletos.", ru = "Подсчёт начинается с первого броска нужды. После этого каждый забег без подтверждённой победы нужды считается, включая незавершённые.", ko = "첫 차비 주사위부터 집계가 시작됩니다. 이후 확인된 차비 승리가 없는 모든 런이 집계되며 미완료 런도 포함됩니다.", zhCN = "从第一次需求掷骰开始计数。之后每个无确认需求胜利的副本都计入，包括未完成的。", zhTW = "從第一次需求擲骰開始計數。之後每個無確認需求勝利的地城都計入，包括未完成的。" },

